from lib import *
S = SS('e10')
steps = [
    step("Huffman 树的构造:每次取出现次数最少的两个合并。例子 abracadabra(a 5 次、b 2、c 1、d 1、r 2,共 11 个符号,0 阶熵 2.0404 bit/符号,理论下限 22.44 位):第 1 步合并 c(1)和 d(1)得 2,第 2 步合并 b(2)和 r(2)得 4,第 3 步合并 cd(2)和 br(4)得 6,第 4 步合并 a(5)和 cdbr(6)得 11。码长 a=1 位,b、c、d、r 各 3 位,规范码 a=0、b=100、c=101、d=110、r=111。编码后 23 位(定长 8 位是 88 位),平均码长 2.0909 bit,接近熵 2.0404 bit。出现多的符号码短,出现少的码长。", t=tl(S(1)), done=lidx(S(1), '码长 {'), mark=lidx(S(1), '第 1 步'), b=bars([['定长 8 位', 88, '88 位'], ['Huffman', 23, '23 位'], ['熵的下限', 22.44, '22.44 位']], 90, done=[1], mark=[0]), kv=KV([['合并规则', '每次取最少的两个'], ['码长', 'a 1 位,b/c/d/r 各 3 位'], ['结果', '23 位对 88 位']], ['结果'])),
    step("真实数据(products JSON Lines 的 1 MiB):用到 59 种不同的字节值,熵 5.1347 bit/字节,Huffman 平均码长 5.1620 bit/字节(只差 0.0273,约 0.53%),最短码 3 位,最长码 11 位。编码后 676591 字节(熵下限 673018 字节,原 1048576 字节,压缩比 1.550×)。最常出现的字节:引号 12.2% → 3 位,e 6.1% → 4 位,a 5.9% → 4 位,t 4.9% → 4 位,冒号 4.4% → 5 位。Huffman 在这份数据上离熵只差 0.5%,但只靠字节频率,压缩比只有 1.55×。", t=tl(S(2)), done=lidx(S(2), 'Huffman 平均码长'), mark=lidx(S(2), '最常出现'), b=bars([['原始 字节', 1048576, '1048576'], ['熵下限', 673018, '673018'], ['Huffman', 676591, '676591']], 1050000, mark=[0], done=[2]), kv=KV([['平均码长', '5.1620 bit(熵 5.1347)'], ['码长范围', '3 位(引号)到 11 位'], ['压缩比', '1.550×']], ['压缩比'])),
    step("分布很偏时 Huffman 的浪费:每个符号至少 1 位。两个符号 0.5/0.5:熵 1.0000,Huffman 1.0000,没浪费;0.9/0.1:熵 0.4690,Huffman 1.0000,多出 113.2%;0.99/0.01:熵 0.0808,Huffman 1.0000,多出 1137.7%;0.999/0.001:熵 0.0114,多出 8666.0%;三个符号 0.7/0.2/0.1:熵 1.1568,Huffman 1.3000,多出 12.4%。把 2 个符号合并成一个再编码,0.9/0.1 降到 0.6450(多 37.5%),合并 4 个降到 0.4925(多 5.0%);0.7/0.2/0.1 合并 2 个就降到 1.1650(多 0.7%)。合并越多越接近熵,但码表按符号个数的幂次增长。", t=tl(S(3)), done=lidx(S(3), '0.9 / 0.1'), mark=lidx(S(3), '0.99 / 0.01'), b=bars([['0.9/0.1 熵', 0.4690, '0.469'], ['0.9/0.1 Huffman', 1.0000, '1.000'], ['0.9/0.1 合并 4 个', 0.4925, '0.4925']], 1.05, mark=[1], done=[2]), kv=KV([['0.9/0.1', 'Huffman 1.0000 对熵 0.4690'], ['合并 4 个符号', '降到 0.4925,多 5.0%'], ['代价', '码表按符号数的幂次增长']], ['代价'])),
    step("规范 Huffman:码表里只存每个符号的码长,解码端按“先按码长、再按符号排序依次分配”的规则重建同一套码。验证:前 100000 字节编码再解码一致(515264 位 = 64408 字节)。码表大小:59 个符号用到的码长,若 256 个位置每个码长用 4 位就是 128 字节(没出现的符号码长为 0);把整棵树存下来约 118 字节;把 256 个码长当作字节数组再用 deflate 压一下只要 69 字节(deflate 自己对码长序列也做了游程加 Huffman)。码表是每个块都要付的固定成本。", t=tl(S(4)), done=lidx(S(4), '编码解码往返'), mark=lidx(S(4), '码表只存码长'), b=bars([['每个码长 4 位(256 个位置)', 128, '128 字节'], ['整棵树', 118, '118 字节'], ['码长数组再压缩', 69, '69 字节']], 130, mark=[0], done=[2]), kv=KV([['规范 Huffman', '只存码长,双方按规则重建'], ['往返验证', '前 100000 字节一致'], ['码表', '128 / 118 / 69 字节(三种存法)']], ['规范 Huffman'])),
    step("限制最大码长(deflate 最长 15 位,zstd 的 Huffman 最长 11 位):这份数据不限制时最长码 11 位,限制到 15 或 11 位都没有变化;限制到 9 位平均码长 5.1647(多 0.053%);限制到 8 位 5.1762(多 0.276%)。限制码长让解码查表更小更快,对压缩比的影响很小。这里用“反复把次数减半直到最长码不超过限制”的简单办法,deflate 和 zstd 用的是更精细的算法,结果会略好一些。", t=tl(S(5)), done=lidx(S(5), '          9'), mark=lidx(S(5), '          8'), b=bars([['不限制 5.1620', 5.1620, '5.1620'], ['限制 9 位', 5.1647, '5.1647'], ['限制 8 位', 5.1762, '5.1762']], 5.2, done=[0, 1], mark=[2]), kv=KV([['限制 11 或 15 位', '与不限制相同(最长本来 11 位)'], ['限制 9 位', '多 0.053%'], ['限制 8 位', '多 0.276%']], ['限制 8 位'])),
    step("只做 Huffman、不做 LZ 匹配(zlib 级别 9,products 的 1 MiB):默认策略(LZ77 + Huffman)213985 字节,压缩比 4.90×;Z_FILTERED 216278(4.85×);Z_HUFFMAN_ONLY(只做 Huffman)677871(1.55×);Z_RLE 677720(1.55×)。我算的 Huffman 理论大小 676591 字节(不含码表),Z_HUFFMAN_ONLY 比它多 1280 字节,是 deflate 每个块的块头和码表。只靠字节频率压缩到 1.55×,LZ77 匹配把它再推到 4.90×——高压缩比大部分来自 LZ 匹配,不是 Huffman。", t=tl(S(6)), done=lidx(S(6), 'Z_DEFAULT_STRATEGY'), mark=lidx(S(6), 'Z_HUFFMAN_ONLY'), b=bars([['Z_HUFFMAN_ONLY', 677871, '677871'], ['默认(LZ77 + Huffman)', 213985, '213985']], 680000, mark=[0], done=[1]), kv=KV([['只做 Huffman', '677871 字节(1.55×)'], ['LZ77 + Huffman', '213985 字节(4.90×)'], ['结论', '大部分压缩比来自 LZ 匹配']], ['结论'])),
]
A = mkarte('e10', 10, '压缩原理,Huffman,熵编码,规范Huffman,deflate,Python,真实验证,动画演示',
    '自己写 Huffman:abracadabra 压成 23 位(定长 88 位);products 文本平均码长只比熵多 0.53%,但压缩比只有 1.55×;分布偏时(0.9/0.1)Huffman 比熵多 113.2%;只做 Huffman 的 zlib 是 1.55×,加上 LZ77 匹配是 4.90×。',
    'Huffman 编码是 gzip、zstd 等压缩器里的熵编码部分:出现越多的符号用越短的码。这篇自己写出来,看它离熵多近、什么时候浪费,以及它在整个压缩里到底贡献了多少。',
    [('0.53%', 'Huffman 平均码长比 products 文本的熵多出的比例(5.1620 对 5.1347 bit/字节)'), ('1.55× 对 4.90×', 'zlib 只做 Huffman 与加上 LZ77 匹配的压缩比(products 的 1 MiB)'), ('113.2%', '0.9/0.1 分布下 Huffman 平均码长(1.0 bit)比熵(0.469 bit)多出的比例')],
    [('Huffman 怎么建', '<p>反复取出现次数最少的两个符号合并,合并的次数就是码长:出现多的符号码短,出现少的码长。abracadabra 的 11 个符号编码成 23 位(定长 88 位),平均码长 2.0909 bit,熵 2.0404 bit。</p>'),
     ('在真实数据上', '<p>products 文本用到 59 种字节值,Huffman 平均码长 5.1620 bit/字节,比熵只多 0.53%,但只靠字节频率压缩比只有 1.55×。Huffman 已经几乎榨干了字节频率,剩下的压缩来自别处。</p>'),
     ('偏斜分布的浪费', '<p>Huffman 每个符号至少一位。概率 0.9/0.1 的二元信源熵只有 0.469 bit,Huffman 用 1 位,多 113.2%。合并多个符号可以逼近熵但码表指数增长。zstd 的 FSE/ANS 用另一种办法解决(第 13 篇)。</p>'),
     ('规范 Huffman 与码表', '<p>解码端只要知道每个符号的码长,就能按固定规则重建同一套码,所以码表只存码长。码表是每个块都要付的固定成本,deflate 还要把码长序列再压缩一遍。</p>'),
     ('限制码长', '<p>deflate 把码长限制在 15 位,zstd 限制在 11 位,让解码用小的查找表。对这份数据限制到 9 位只多 0.053%,代价很小。</p>'),
     ('Huffman 贡献了多少', '<p>只做 Huffman(zlib 的 Z_HUFFMAN_ONLY)是 1.55×,加上 LZ77 匹配是 4.90×。gzip 的高压缩比主要来自 LZ 匹配把重复内容替换掉,Huffman 再把剩下的符号编码得更紧。LZ77 见下一篇。</p>')],
    steps,
    [ENV_E + '。Huffman 构造、规范码、编码解码是我手写的 Python 实现(往返验证通过);zlib 的各种策略用 raw deflate(窗口 15 位、内存级别 9);所有数字都是确定性的',
     '没有验证:zstd 内部 Huffman 的实现细节(例如它对字面量的 4 路流和权重表示);deflate 自己的最优码长限制算法(package-merge 类);Huffman 解码的速度;自适应 Huffman;算术编码与 Huffman 的对照(见 FSE/ANS 那一篇)'],
    'Huffman 编码')
